alter table public.beta_invitations add constraint beta_invitations_pkey PRIMARY KEY (id);
alter table public.beta_invitations add constraint beta_invitations_revocation_pair CHECK (revoked_at IS NULL AND revoked_by IS NULL AND revoke_reason IS NULL OR revoked_at IS NOT NULL AND revoke_reason IS NOT NULL);
alter table public.beta_invitations add constraint beta_invitations_revoked_by_fkey FOREIGN KEY (revoked_by) REFERENCES auth.users(id) ON DELETE SET NULL;
